var SHELL = _global.getCurrentShell();
var ENGINE = _global.getCurrentEngine();
var start_x = 420;
var start_y = 340;
if(SHELL.isMigratorHere())
{
   background_mc.ship_mc._visible = true;
}
else
{
   background_mc.ship_mc._visible = false;
}
var SHELL = _global.getCurrentShell();
var language;
var localized_frame = 3;
if(SHELL.getLocalizedFrame != undefined)
{
   localized_frame = SHELL.getLocalizedFrame();
}
switch(localized_frame)
{
   case 1:
      language = "english";
      break;
   case 2:
      language = "portuguese";
      break;
   case 3:
      language = "french";
      break;
   case 4:
      language = "spanish";
      break;
   default:
      language = "english";
}
background_mc.board_mc_states.gotoAndStop(language);
beans_btn_states.gotoAndStop(language);
background_mc.coffeebag_mc_states.gotoAndStop(language);
background_mc.wall.coffeeshop_mc_states.gotoAndStop(language);
background_mc.wall.exit_mc_states.gotoAndStop(language);
background_mc.town_btn_states.gotoAndStop(language);
background_mc.ship_mc.migratortext_mc.gotoAndStop(language);
triggers_mc.light_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("light",320,310);
};
triggers_mc.ship_mc.triggerFunction = function()
{
   if(SHELL.isMigratorHere())
   {
      ENGINE.sendJoinRoom("ship",440,300);
   }
};
triggers_mc.village_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("village",225,375);
};
triggers_mc.dock_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("dock",120,210);
};
background_mc.light_btn.onRelease = function()
{
   ENGINE.sendPlayerMove(240,200);
};
bucket_btn.onRollOver = function()
{
   if(cash_mc._currentframe == 1)
   {
      cash_mc.gotoAndPlay(2);
   }
   else if(cash_mc._currentframe == 70)
   {
      cash_mc.gotoAndPlay(71);
   }
   else if(cash_mc._currentframe == 137)
   {
      cash_mc.gotoAndPlay(138);
   }
   else if(cash_mc._currentframe == 210)
   {
      cash_mc.gotoAndPlay(211);
   }
   else if(cash_mc._currentframe == 269)
   {
      cash_mc.gotoAndPlay(270);
   }
};
triggers_mc._visible = false;
block_mc._visible = false;
